const finance = window.financeDemo;
const root = document.documentElement;
const filters = document.querySelector('#movementFilters');
const rows = document.querySelector('#movementRows');
const dialog = document.querySelector('#movementDialog');
const form = document.querySelector('#movementForm');
let selectedMovement;
let toastTimer;

function setTheme(theme) { root.dataset.theme = theme; const button = document.querySelector('.theme-button'); const dark = theme === 'dark'; button.setAttribute('aria-pressed', String(dark)); button.querySelector('.theme-label').textContent = dark ? 'Modo claro' : 'Modo oscuro'; localStorage.setItem('pw-theme', theme); }
function typeLabel(type) { return ({ sale: 'Venta', expense: 'Gasto', withdrawal: 'Retiro', investment: 'Inversión', income: 'Ingreso', 'loan-payment': 'Pago', 'loan-disbursement': 'Desembolso' })[type] || 'Préstamo'; }
function originLabel(origin) { return ({ manual: 'Manual', sale: 'Venta', loan: 'Préstamo' })[origin]; }
function getFiltered() { const data = new FormData(filters); const term = data.get('search').trim().toLowerCase(); return finance.movements.filter((movement) => (!data.get('period') || data.get('period') === 'all' || movement.date.startsWith(data.get('period'))) && (!data.get('type') || movement.type === data.get('type')) && (!data.get('origin') || movement.origin === data.get('origin')) && (!term || `${movement.concept} ${movement.category}`.toLowerCase().includes(term))).sort((a, b) => b.date.localeCompare(a.date)); }
function renderDetail(movement) { const detail = document.querySelector('#movementDetail'); document.querySelector('#ledgerLayout').classList.remove('is-no-detail'); detail.hidden = false; detail.innerHTML = `<h3>${movement.concept}</h3><span class="origin-badge is-${movement.origin}">${originLabel(movement.origin)}</span><dl><div><dt>Fecha</dt><dd>${movement.date}</dd></div><div><dt>Tipo</dt><dd>${typeLabel(movement.type)}</dd></div><div><dt>Categoría</dt><dd>${movement.category}</dd></div><div><dt>Monto</dt><dd class="amount-${movement.direction}">${movement.direction === 'inflow' ? '+' : '−'}${finance.formatMoney(movement.amount)}</dd></div></dl>${movement.source ? `<a class="secondary-action" href="${movement.source}">Ver registro de origen</a>` : movement.origin === 'manual' ? '<button class="secondary-action" type="button" disabled>Edición disponible en la versión conectada</button>' : ''}`; }
function renderMovements() { const movements = getFiltered(); document.querySelector('#movementCount').textContent = `${movements.length} movimiento${movements.length === 1 ? '' : 's'}`; rows.innerHTML = movements.map((movement) => `<tr class="ledger-row ${selectedMovement?.id === movement.id ? 'is-selected' : ''}" data-id="${movement.id}" tabindex="0"><td>${movement.date}</td><td><button type="button">${movement.concept}</button><small>${movement.category}</small></td><td><span class="type-badge">${typeLabel(movement.type)}</span></td><td><span class="origin-badge is-${movement.origin}">${originLabel(movement.origin)}</span></td><td class="amount-inflow">${movement.direction === 'inflow' ? finance.formatMoney(movement.amount) : '—'}</td><td class="amount-outflow">${movement.direction === 'outflow' ? finance.formatMoney(movement.amount) : '—'}</td></tr>`).join(''); document.querySelector('#movementEmpty').hidden = movements.length > 0; if (selectedMovement && movements.some((movement) => movement.id === selectedMovement.id)) renderDetail(selectedMovement); }
function syncFields() { const type = document.querySelector('#movementType').value; document.querySelector('#categoryField').hidden = type !== 'expense'; document.querySelector('#purposeField').hidden = !['withdrawal', 'investment', 'income'].includes(type); }
function showToast(message) { const toast = document.querySelector('#financeToast'); clearTimeout(toastTimer); toast.textContent = message; toast.hidden = false; toastTimer = setTimeout(() => { toast.hidden = true; }, 3200); }
function openDialog() { form.reset(); document.querySelector('#movementError').hidden = true; syncFields(); dialog.showModal(); document.querySelector('#movementType').focus(); }

setTheme(localStorage.getItem('pw-theme') || 'light');
document.querySelector('.theme-button').addEventListener('click', () => setTheme(root.dataset.theme === 'dark' ? 'light' : 'dark'));
renderMovements();
filters.addEventListener('input', renderMovements); filters.addEventListener('change', renderMovements);
rows.addEventListener('click', (event) => { const row = event.target.closest('tr'); if (!row) return; selectedMovement = finance.movements.find((movement) => movement.id === row.dataset.id); renderMovements(); });
rows.addEventListener('keydown', (event) => { if (event.key === 'Enter' || event.key === ' ') { event.preventDefault(); event.target.closest('tr').click(); } });
document.querySelector('#openMovementDialog').addEventListener('click', openDialog); document.querySelector('.dialog-close').addEventListener('click', () => dialog.close()); document.querySelector('[data-close-dialog]').addEventListener('click', () => dialog.close()); document.querySelector('#movementType').addEventListener('change', syncFields);
form.addEventListener('submit', (event) => { event.preventDefault(); const data = Object.fromEntries(new FormData(form)); const result = finance.addManualMovement(data); const error = document.querySelector('#movementError'); if (!result.ok) { error.textContent = result.error; error.hidden = false; return; } dialog.close(); selectedMovement = result.movements[0]; renderMovements(); renderDetail(selectedMovement); showToast('Movimiento registrado y saldos actualizados.'); });
if (new URLSearchParams(location.search).get('new') === '1') openDialog();
